import{_ as p,a0 as l,w as o,s as d,ao as r,I as t,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"scanimage：从命令行扫描! | LCTT x X-CMD","titleTemplate":false,"description":"scanimage：从命令行扫描! | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"scanimage：从命令行扫描! | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"scanimage：从命令行扫描! | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20200711 scanimage- scan from the command line","title":"scanimage：从命令行扫描!","tag":"202012","desc":""},"relativePath":"202012/20200711 scanimage- scan from the command line.md","filePath":"[post].md"}'),c={name:"202012/20200711 scanimage- scan from the command line.md"};function m(g,a,h,u,f,b){const s=l("Link");return o(),d("div",null,[a[15]||(a[15]=r(`<h1 id="scanimage-从命令行扫描" tabindex="-1">scanimage：从命令行扫描! <a class="header-anchor" href="#scanimage-从命令行扫描" aria-label="Permalink to “scanimage：从命令行扫描!”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202012/05/105822m30t6x66hz3hx6x3.jpg" alt=""></p><p>这又是一篇关于我很喜欢的一个命令行工具的文章。</p><p>昨晚，出于官僚原因，我需要扫描一些文档。我以前从来没有在 Linux 上使用过扫描仪，我担心会花上好几个小时才弄明白。我从使用 <code>gscan2pdf</code> 开始，但在用户界面上遇到了麻烦。我想同时扫描两面（我知道我们的扫描仪支持），但无法使它工作。</p><h3 id="遇到-scanimage" tabindex="-1">遇到 scanimage！ <a class="header-anchor" href="#遇到-scanimage" aria-label="Permalink to “遇到 scanimage！”">​</a></h3><p><code>scanimage</code> 是一个命令行工具，在 <code>sane-utils</code> Debian 软件包中。我想所有的 Linux 扫描工具都使用 <code>sane</code> （“scanner access now easy”） 库，所以我猜测它和其他扫描软件有类似的能力。在这里，我不需要 OCR，所以我不打算谈论 OCR。</p><h3 id="用-scanimage-l-得到你的扫描仪的名字" tabindex="-1">用 scanimage -L 得到你的扫描仪的名字 <a class="header-anchor" href="#用-scanimage-l-得到你的扫描仪的名字" aria-label="Permalink to “用 scanimage -L 得到你的扫描仪的名字”">​</a></h3><p><code>scanimage -L</code> 列出了你所有的扫描设备。</p><p>一开始我不能让它工作，我有点沮丧，但事实证明，我把扫描仪连接到了我的电脑上，但没有插上电源。</p><p>插上后，它马上就能工作了。显然我们的扫描仪叫 <code>fujitsu:ScanSnap S1500:2314</code>。万岁！</p><h3 id="用-help-列出你的扫描仪选项" tabindex="-1">用 --help 列出你的扫描仪选项 <a class="header-anchor" href="#用-help-列出你的扫描仪选项" aria-label="Permalink to “用 --help 列出你的扫描仪选项”">​</a></h3><p>显然每个扫描仪有不同的选项（有道理！），所以我运行这个命令来获取我的扫描仪的选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scanimage --help -d &#39;fujitsu:ScanSnap S1500:2314&#39;</span></span></code></pre></div><p>我发现我的扫描仪支持 <code>--source</code> 选项（我可以用它来启用双面扫描）和 <code>--resolution</code> 选项（我把它改为 150，以减少文件大小，使扫描更快）。</p><h3 id="scanimage-不支持输出-pdf-文件-但你可以写一个小脚本" tabindex="-1">scanimage 不支持输出 PDF 文件（但你可以写一个小脚本） <a class="header-anchor" href="#scanimage-不支持输出-pdf-文件-但你可以写一个小脚本" aria-label="Permalink to “scanimage 不支持输出 PDF 文件（但你可以写一个小脚本）”">​</a></h3><p>唯一的缺点是：我想要一个 PDF 格式的扫描文件，而 scanimage 似乎不支持 PDF 输出。</p><p>所以我写了这个 5 行的 shell 脚本在一个临时文件夹中扫描一堆 PNG 文件，并将结果保存到 PDF 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DIR=\`mktemp -d\`</span></span>
<span class="line"><span>CUR=$PWD</span></span>
<span class="line"><span>cd $DIR</span></span>
<span class="line"><span>scanimage -b --format png  -d &#39;fujitsu:ScanSnap S1500:2314&#39; --source &#39;ADF Front&#39; --resolution 150</span></span>
<span class="line"><span>convert *.png $CUR/$1</span></span></code></pre></div><p>我像这样运行脚本：<code>scan-single-sided output-file-to-save.pdf</code></p><p>你可能需要为你的扫描仪设置不同的 <code>-d</code> 和 <code>-source</code>。</p><h3 id="这真是太简单了" tabindex="-1">这真是太简单了! <a class="header-anchor" href="#这真是太简单了" aria-label="Permalink to “这真是太简单了!”">​</a></h3><p>我一直以为在 Linux 上使用打印机/扫描仪是一个噩梦，我真的很惊讶 <code>scanimage</code> 可以工作。我可以直接运行我的脚本 <code>scan-single-sided receipts.pdf</code>，它将扫描文档并将其保存到 <code>receipts.pdf</code>！</p><hr>`,23)),t("p",null,[a[1]||(a[1]=e("via: ",-1)),n(s,{href:"https://jvns.ca/blog/2020/07/11/scanimage--scan-from-the-command-line/"},{default:i(()=>[...a[0]||(a[0]=[e("https://jvns.ca/blog/2020/07/11/scanimage--scan-from-the-command-line/",-1)])]),_:1})]),t("p",null,[a[6]||(a[6]=e("作者：",-1)),n(s,{href:"https://jvns.ca/"},{default:i(()=>[...a[2]||(a[2]=[e("Julia Evans",-1)])]),_:1}),a[7]||(a[7]=e(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:i(()=>[...a[4]||(a[4]=[e("geekpi",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const T=p(c,[["render",m]]);export{C as __pageData,T as default};
